-- Root-scope regression coverage for information_schema routine and dependency views.
-- Master files are generated by the integration environment.

USE defaultdb;
DROP DATABASE IF EXISTS is_views_03 CASCADE;
CREATE DATABASE is_views_03;
SET DATABASE = is_views_03;

CREATE TABLE base_table (
    id INT PRIMARY KEY,
    value VARCHAR(8)
);
CREATE TABLE trigger_log (id INT PRIMARY KEY);

CREATE VIEW direct_view AS
SELECT id, value FROM base_table;
CREATE VIEW nested_view AS
SELECT id FROM direct_view;

CREATE PROCEDURE is_views_03_proc(proc_id INT, proc_name VARCHAR(5)) BEGIN SELECT proc_id; END;

CREATE TRIGGER is_views_03_before_insert BEFORE INSERT ON base_table FOR EACH ROW BEGIN INSERT INTO trigger_log VALUES (NEW.id); END;

-- routines: procedure identity, SQL body, definition, nullable result type,
-- and definer as seen by root.
SELECT specific_catalog, specific_schema, specific_name,
       routine_catalog, routine_schema, routine_name, routine_type,
       routine_body, external_language, routine_definition IS NOT NULL AS has_definition,
       dtd_identifier, definer
FROM information_schema.routines
WHERE routine_name = 'is_views_03_proc';

-- parameters: parameter order, names, input mode, type metadata, and routine type.
SELECT specific_catalog, specific_schema, specific_name, ordinal_position,
       parameter_mode, is_result, parameter_name, data_type,
       character_maximum_length, character_octet_length,
       numeric_precision, numeric_precision_radix, numeric_scale,
       udt_catalog, udt_schema, udt_name, dtd_identifier,
       declared_data_type, declared_numeric_precision, declared_numeric_scale,
       routine_type
FROM information_schema.parameters
WHERE specific_name = 'is_views_03_proc'
ORDER BY ordinal_position;

-- view_table_usage: direct table and view dependencies visible to root.
SELECT view_catalog, view_schema, view_name,
       table_catalog, table_schema, table_name
FROM information_schema.view_table_usage
WHERE view_name IN ('direct_view', 'nested_view')
ORDER BY view_name, table_name;

-- triggers: trigger identity, event/table metadata, stored action text, and
-- the currently unsupported SQL-standard reference and creation fields.
SELECT trigger_catalog, trigger_schema, trigger_name,
       event_manipulation, event_object_catalog, event_object_schema, event_object_table,
       action_order, action_condition, action_statement IS NOT NULL AS has_action_statement,
       action_orientation, action_timing,
       action_reference_old_table, action_reference_new_table,
       action_reference_old_row, action_reference_new_row, created
FROM information_schema.triggers
WHERE trigger_name = 'is_views_03_before_insert';

USE defaultdb;
DROP DATABASE is_views_03 CASCADE;
